import os, json, re, glob
import xml.etree.ElementTree as ET

base = '/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_10'

def norm(s):
    return re.sub(r'\s+', ' ', (s or '')).strip()

def extract_meta(txt):
    m = {}
    pk = sorted(set(re.findall(r'CBP-031-\d+', txt)))
    ent = sorted(set(re.findall(r'ENT-031-\d+', txt)))
    rev = sorted(set(re.findall(r'REV-20\d\d\.\d+', txt)))
    ref = sorted(set(re.findall(r'CB-LD-2701-[A-Z]\d+', txt)))
    role = sorted(set(re.findall(r'(identity_crosswalk|operative_authority|current_operations|approval_and_capacity|correspondence|financial_or_population_support|chronology_and_custody|independent_counterrecord)', txt)))
    return {'pk': pk, 'ent': ent, 'rev': rev, 'ref': ref, 'role': role}

for fmt in ['txt','eml','xml','html']:
    print(f"\n########## {fmt.upper()} ##########")
    for f in sorted(glob.glob(base + f'/*/*.{fmt}')):
        cat = os.path.basename(os.path.dirname(f))
        fn = os.path.basename(f)
        txt = open(f, errors='ignore').read()
        m = extract_meta(txt)
        # find native record / body sentence
        body = ''
