import os, json, re, glob
from pypdf import PdfReader
base = '/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_10'

def norm(s): return re.sub(r'\s+',' ', s or '').strip()

def xml_body(f):
    t = open(f).read()
    m = re.search(r'<native_record[^>]*>(.*?)</native_record>', t, re.S)
    if m: return norm(re.sub(r'<[^>]+>',' ',m.group(1)))
    m2 = re.search(r'<body[^>]*>(.*?)</body>', t, re.S)
    if m2: return norm(re.sub(r'<[^>]+>',' ',m2.group(1)))
    return ''

def txt_body(f):
    t = open(f).read()
    m = re.search(r'NATIVE RECORD\s*\n+(.*?)(?:\nSOURCE|\nBUSINESS|\nRELIANCE|\nSCHEDULE)', t, re.S)
    if m: return norm(m.group(1))
    return ''

def eml_html_body(f):
    t = open(f, errors='ignore').read()
    t2 = re.sub(r'<[^>]+>',' ', t)
    # look for body-like sentence
    m = re.search(r'(?:Body|Native record|native_record)[:\s]+(.{0,400})', t2)
    if m: return norm(m.group(1))
    return norm(t2)[:250]

def csv_body(f):
    t = open(f).read()
    m = re.search(r',body,"([^"]+)"', t)
    if m: return norm(m.group(1))
    # subject
    m2 = re.search(r',subject,([^,]+),', t)
    return (norm(m2.group(1)) if m2 else '') + ' | ' + norm(t[:150])

